command:
let dinerId = null;
try {
  if (Array.isArray(args) && args[0]?.id) dinerId = String(args[0].id);
  else if (Array.isArray(args) && typeof args[0] === "string") dinerId = String(args[0]).replace(/^id\s*=\s*/i, "");
  else if (!Array.isArray(args) && args?.id) dinerId = String(args.id);
} catch {}
if (!dinerId) return ui.notifications.warn("Diner ID missing. Use id=YOUR-DINER-ID.");
game.dinerManager.open(dinerId.replace(/[<>"'()\[\]\s]/g, ""));
